import { getStroke } from 'perfect-freehand';
import { Point } from '../types';

/**
 * Converts a polygon outline generated by perfect-freehand into a closed SVG path string.
 */
function getSvgPathFromStroke(stroke: number[][]): Path2D {
  if (!stroke.length) return new Path2D();

  const d: string[] = [];
  const [firstX, firstY] = stroke[0];
  d.push(`M ${firstX.toFixed(2)} ${firstY.toFixed(2)}`);

  for (let i = 1; i < stroke.length; i++) {
    const [p0x, p0y] = stroke[i - 1];
    const [p1x, p1y] = stroke[i];
    const midX = (p0x + p1x) / 2;
    const midY = (p0y + p1y) / 2;
    d.push(`Q ${p0x.toFixed(2)} ${p0y.toFixed(2)} ${midX.toFixed(2)} ${midY.toFixed(2)}`);
  }

  d.push('Z');
  return new Path2D(d.join(' '));
}

/**
 * State-of-the-art ink stroke renderer for Apple Pencil & Android Stylus.
 * Uses perfect-freehand polygon generation with pressure & velocity smoothing.
 */
export function drawStroke(
  ctx: CanvasRenderingContext2D,
  points: Point[],
  color: string,
  baseWidth: number,
  opacity: number = 1.0,
  isHighlighter: boolean = false,
  lineStyle?: 'solid' | 'dashed' | 'dotted'
) {
  if (points.length === 0) return;

  ctx.save();
  ctx.fillStyle = color;
  ctx.strokeStyle = color;

  if (isHighlighter) {
    // Highlighter: broad translucent stroke with round caps
    ctx.globalAlpha = 0.36;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.lineWidth = baseWidth * 5.5;

    if (points.length === 1) {
      ctx.beginPath();
      ctx.arc(points[0].x, points[0].y, (baseWidth * 5.5) / 2, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
      return;
    }

    ctx.beginPath();
    ctx.moveTo(points[0].x, points[0].y);
    for (let i = 1; i < points.length; i++) {
      const midX = (points[i - 1].x + points[i].x) / 2;
      const midY = (points[i - 1].y + points[i].y) / 2;
      ctx.quadraticCurveTo(points[i - 1].x, points[i - 1].y, midX, midY);
    }
    const last = points[points.length - 1];
    ctx.lineTo(last.x, last.y);
    ctx.stroke();
    ctx.restore();
    return;
  }

  if (lineStyle === 'dashed' || lineStyle === 'dotted') {
    ctx.globalAlpha = opacity;
    ctx.lineWidth = baseWidth * 1.6;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.setLineDash(lineStyle === 'dashed' ? [12, 8] : [3, 7]);
    ctx.beginPath();
    ctx.moveTo(points[0].x, points[0].y);
    for (let i = 1; i < points.length; i++) {
      const midX = (points[i - 1].x + points[i].x) / 2;
      const midY = (points[i - 1].y + points[i].y) / 2;
      ctx.quadraticCurveTo(points[i - 1].x, points[i - 1].y, midX, midY);
    }
    const last = points[points.length - 1];
    ctx.lineTo(last.x, last.y);
    ctx.stroke();
    ctx.restore();
    return;
  }

  // Pen Tool: Perfect-freehand polygon outline
  ctx.globalAlpha = opacity;

  // Format points as [x, y, pressure]
  const inputPoints = points.map(p => [p.x, p.y, p.pressure > 0 ? p.pressure : 0.5]);

  const outline = getStroke(inputPoints, {
    size: baseWidth * 1.8,
    thinning: 0.65,      // Pressure-responsive tapering
    smoothing: 0.55,     // Catmull-Rom curve smoothing
    streamline: 0.45,    // Stabilizes hand jitter
    easing: (t) => t,
    start: {
      taper: 0,
      cap: true
    },
    end: {
      taper: 0,
      cap: true
    }
  });

  const path = getSvgPathFromStroke(outline);
  ctx.fill(path);

  ctx.restore();
}
